test("grace per grade scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "cap", "2.00");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "0");
  await ui.setSetting(pg_uma, "grace-B", "2");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50", "from": "2026-03-01"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "3"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "20"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  await ui.setToday(pg_uma, "2026-04-02");
  expect(await ui.addClaim(pg_uma, p_ada, {"amount": "3.33", "date": "2026-02-25", "note": "n"})).toBeNull();
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "20.00"}));
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.delegate(pg_vic, {"user": "uma", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.periodAction(pg_uma, "2026-04", "soft-close")).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.reassign(pg_vic, c_ben_0, "Ada")).toBe(true);
  expect(await ui.addPatron(pg_vic, p_ben, "Ada")).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.bulkGrade(pg_vic, [p_ben, p_ada], {"grade": "C"})).toBe(2);
  expect(await ui.statement(pg_vic, p_ben)).toBe(true);
  expect(await ui.editPerson(pg_vic, p_ben, {"terms": ""})).toBe(true);
  expect(await ui.addProof(pg_vic, c_ben_0)).toBe(true);
  expect(await ui.editPerson(pg_vic, p_cam, {"terms": "3"})).toBe(true);
  expect(await ui.claimEditOpen(pg_vic, c_ben_0)).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimEditOpen(pg_wes, c_ben_0)).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.claimEditSave(pg_vic, c_ben_0, {"amount": "3.33"})).toBe(true);
  expect(await ui.addClaim(pg_vic, p_ada, {"amount": "10.25", "date": "2026-03-01"})).toBeNull();
  await ui.refresh(pg_vic);
  const c_cam_0 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "3.33", "date": "2026-04-02", "note": "n"}));
  expect(await ui.bulkOpen(pg_vic, [c_ben_0, c_cam_0])).toEqual({ opened: 2, refused: 0 });
  expect(await ui.statementAsOf(pg_vic, p_ada, "2026-02-25")).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.redate(pg_vic, c_ben_0, "2026-02-10")).toBe(true);
  await ui.setToday(pg_vic, "2026-04-11");
  await ui.refresh(pg_vic);
  await ui.expectAudit(sheet, [
  ]);
});

