    if (this.pctOf(gradeToday) === null && !counted.some(fixed)) return null;
    return counted.reduce((sum, c) => sum + (claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs)) ?? 0), 0);
  }

  /** The sheet's cap in cents, or null when there is none. */

